import {
  loadSDKFactory2
} from "./repository-cache-6q2bdcd1.js";

// src/plugin/provider/dynamic.ts
import { Effect } from "effect";
import { define } from "@opencode/plugin/effect/plugin";
import { Npm } from "@opencode/util/npm";
var DynamicProviderPlugin2 = define({
  id: "opencode.provider.dynamic",
  effect: Effect.fn(function* (ctx) {
    const npm = yield* Npm.Service;
    yield* ctx.aisdk.hook("sdk", Effect.fn(function* (evt) {
      if (evt.sdk)
        return;
      evt.sdk = (yield* loadSDKFactory2(npm, evt.package))(evt.options);
    }));
  })
});

export { DynamicProviderPlugin2 };
